71	unsafe fn report_error(ctx: *mut sqlite3_context, err: &Error) {
72	    unsafe {
73	        if let Error::SqliteFailure(ref err, ref s) = *err {
74	            ffi::sqlite3_result_error_code(ctx, err.extended_code);
75	            if let Some(Ok(cstr)) = s.as_ref().map(|s| str_to_cstring(s)) {
76	                ffi::sqlite3_result_error(ctx, cstr.as_ptr(), -1);
77	            }
78	        } else {
79	            ffi::sqlite3_result_error_code(ctx, ffi::SQLITE_CONSTRAINT_FUNCTION);
80	            if let Ok(cstr) = str_to_cstring(&err.to_string()) {
81	                ffi::sqlite3_result_error(ctx, cstr.as_ptr(), -1);
82	            }
83	        }
84	    }
85	}
