282	/// A reference to a connection handle with a lifetime bound to something.
283	pub struct ConnectionRef<'ctx> {
284	    // comes from Connection::from_handle(sqlite3_context_db_handle(...))
285	    // and is non-owning
286	    conn: Connection,
287	    phantom: PhantomData<&'ctx Context<'ctx>>,
288	}
289	
290	impl Deref for ConnectionRef<'_> {
291	    type Target = Connection;
292	
293	    #[inline]
294	    fn deref(&self) -> &Connection {
295	        &self.conn
296	    }
297	}
