361	/// Aggregate is the callback interface for user-defined
362	/// aggregate function.
363	///
364	/// `A` is the type of the aggregation context and `T` is the type of the final
365	/// result. Implementations should be stateless.
366	pub trait Aggregate<A, T>
367	where
368	    A: RefUnwindSafe + UnwindSafe,
369	    T: SqlFnOutput,
370	{
371	    /// Initializes the aggregation context. Will be called prior to the first
372	    /// call to [`step()`](Aggregate::step) to set up the context for an
373	    /// invocation of the function. (Note: `init()` will not be called if
374	    /// there are no rows.)
375	    fn init(&self, ctx: &mut Context<'_>) -> Result<A>;
376	
377	    /// "step" function called once for each row in an aggregate group. May be
378	    /// called 0 times if there are no rows.
379	    fn step(&self, ctx: &mut Context<'_>, acc: &mut A) -> Result<()>;
380	
381	    /// Computes and returns the final result. Will be called exactly once for
382	    /// each invocation of the function. If [`step()`](Aggregate::step) was
383	    /// called at least once, will be given `Some(A)` (the same `A` as was
384	    /// created by [`init`](Aggregate::init) and given to
385	    /// [`step`](Aggregate::step)); if [`step()`](Aggregate::step) was not
386	    /// called (because the function is running against 0 rows), will be
387	    /// given `None`.
388	    ///
389	    /// The passed context will have no arguments.
390	    fn finalize(&self, ctx: &mut Context<'_>, acc: Option<A>) -> Result<T>;
391	}
392	
393	/// `WindowAggregate` is the callback interface for
394	/// user-defined aggregate window function.
395	#[cfg(feature = "window")]
396	pub trait WindowAggregate<A, T>: Aggregate<A, T>
397	where
398	    A: RefUnwindSafe + UnwindSafe,
399	    T: SqlFnOutput,
400	{
401	    /// Returns the current value of the aggregate. Unlike xFinal, the
402	    /// implementation should not delete any context.
403	    fn value(&self, acc: Option<&mut A>) -> Result<T>;
404	
405	    /// Removes a row from the current window.
406	    fn inverse(&self, ctx: &mut Context<'_>, acc: &mut A) -> Result<()>;
407	}
