565	impl InnerConnection {
566	    /// ```compile_fail
567	    /// use rusqlite::{functions::FunctionFlags, Connection, Result};
568	    /// fn main() -> Result<()> {
569	    ///     let db = Connection::open_in_memory()?;
570	    ///     {
571	    ///         let mut called = std::sync::atomic::AtomicBool::new(false);
572	    ///         db.create_scalar_function(
573	    ///             "test",
574	    ///             0,
575	    ///             FunctionFlags::SQLITE_UTF8 | FunctionFlags::SQLITE_DETERMINISTIC,
576	    ///             |_| {
577	    ///                 called.store(true, std::sync::atomic::Ordering::Relaxed);
578	    ///                 Ok(true)
579	    ///             },
580	    ///         );
581	    ///     }
582	    ///     let result: Result<bool> = db.query_row("SELECT test()", [], |r| r.get(0));
583	    ///     assert!(result?);
584	    ///     Ok(())
585	    /// }
586	    /// ```
587	    fn create_scalar_function<F, N: Name, T>(
588	        &mut self,
589	        fn_name: N,
590	        n_arg: c_int,
591	        flags: FunctionFlags,
592	        x_func: F,
593	    ) -> Result<()>
594	    where
595	        F: Fn(&Context<'_>) -> Result<T> + Send + 'static,
596	        T: SqlFnOutput,
597	    {
598	        unsafe extern "C" fn call_boxed_closure<F, T>(
599	            ctx: *mut sqlite3_context,
600	            argc: c_int,
601	            argv: *mut *mut sqlite3_value,
602	        ) where
603	            F: Fn(&Context<'_>) -> Result<T>,
604	            T: SqlFnOutput,
605	        {
606	            unsafe {
607	                let args = slice::from_raw_parts(argv, argc as usize);
608	                let r = catch_unwind(|| {
609	                    let boxed_f: *const F = ffi::sqlite3_user_data(ctx).cast::<F>();
610	                    assert!(!boxed_f.is_null(), "Internal error - null function pointer");
611	                    let ctx = Context { ctx, args };
612	                    (*boxed_f)(&ctx)
613	                });
614	                let Ok(r) = r else {
615	                    report_error(ctx, &Error::UnwindingPanic);
616	                    return;
617	                };
618	                sql_result(ctx, args, r);
619	            }
620	        }
621	
622	        let boxed_f: *mut F = Box::into_raw(Box::new(x_func));
623	        let c_name = fn_name.as_cstr()?;
624	        let r = unsafe {
625	            ffi::sqlite3_create_function_v2(
626	                self.db(),
627	                c_name.as_ptr(),
628	                n_arg,
629	                flags.bits(),
630	                boxed_f.cast::<c_void>(),
631	                Some(call_boxed_closure::<F, T>),
632	                None,
633	                None,
634	                Some(free_boxed_value::<F>),
635	            )
636	        };
637	        self.decode_result(r)
638	    }
