849	#[cfg(feature = "window")]
850	unsafe extern "C" fn call_boxed_value<A, W, T>(ctx: *mut sqlite3_context)
851	where
852	    A: RefUnwindSafe + UnwindSafe,
853	    W: WindowAggregate<A, T>,
854	    T: SqlFnOutput,
855	{
856	    unsafe {
857	        // Within the xValue callback, it is customary to set N=0 in calls to
858	        // sqlite3_aggregate_context(C,N) so that no pointless memory allocations occur.
859	        let pac = aggregate_context::<A>(ctx, 0).filter(|&pac| !(*pac).is_null());
860	
861	        let r = catch_unwind(|| {
862	            let boxed_aggr: *mut W = ffi::sqlite3_user_data(ctx).cast::<W>();
863	            assert!(
864	                !boxed_aggr.is_null(),
865	                "Internal error - null aggregate pointer"
866	            );
867	            (*boxed_aggr).value(pac.map(|pac| &mut **pac))
868	        });
869	        let Ok(r) = r else {
870	            report_error(ctx, &Error::UnwindingPanic);
871	            return;
872	        };
873	        sql_result(ctx, &[], r);
874	    }
875	}
