179	    pub fn prepare<'a>(
180	        &mut self,
181	        conn: &'a Connection,
182	        sql: &str,
183	        flags: PrepFlags,
184	    ) -> Result<(Statement<'a>, usize)> {
185	        let mut c_stmt: *mut ffi::sqlite3_stmt = ptr::null_mut();
186	        let Ok(len) = c_int::try_from(sql.len()) else {
187	            return Err(err!(ffi::SQLITE_TOOBIG));
188	        };
189	        let c_sql = sql.as_bytes().as_ptr().cast::<c_char>();
190	        let mut c_tail: *const c_char = ptr::null();
191	        let r = cfg_select! {
192	            feature = "unlock_notify" => {
193	                // no_fmt
194	                unsafe {
195	                    use crate::unlock_notify;
196	                    let mut rc;
197	                    loop {
198	                        rc = ffi::sqlite3_prepare_v3(
199	                            self.db(),
200	                            c_sql,
201	                            len,
202	                            flags.bits(),
203	                            &raw mut c_stmt,
204	                            &raw mut c_tail,
205	                        );
206	                        if !unlock_notify::is_locked(self.db, rc) {
207	                            break;
208	                        }
209	                        rc = unlock_notify::wait_for_unlock_notify(self.db);
210	                        if rc != ffi::SQLITE_OK {
211	                            break;
212	                        }
213	                    }
214	                    rc
215	                }
216	            }
217	            _ => {
218	                // no_fmt
219	                unsafe {
220	                    ffi::sqlite3_prepare_v3(
221	                        self.db(),
222	                        c_sql,
223	                        len,
224	                        flags.bits(),
225	                        &mut c_stmt,
226	                        &mut c_tail,
227	                    )
228	                }
229	            }
230	        };
231	        // If there is an error, *ppStmt is set to NULL.
232	        if r != ffi::SQLITE_OK {
233	            return Err(unsafe { error_with_offset(self.db, r, sql) });
234	        }
235	        // If the input text contains no SQL (if the input is an empty string or a
236	        // comment) then *ppStmt is set to NULL.
237	        let tail = if c_tail.is_null() {
238	            0
239	        } else {
240	            let n = (c_tail as isize) - (c_sql as isize);
241	            if n <= 0 || n >= len as isize {
242	                0
243	            } else {
244	                n as usize
245	            }
246	        };
247	        Ok((
248	            Statement::new(conn, unsafe { RawStatement::new(c_stmt) }),
249	            tail,
250	        ))
251	    }
