360	            ffi::sqlite3_set_clientdata(
361	                self.db,
362	                name.as_ptr(),
363	                ptr.cast::<c_void>(),
364	                if ptr.is_null() {
365	                    None
366	                } else {
367	                    Some(crate::util::free_boxed_value::<T>)
368	                },
