416	#[cfg(not(any(target_arch = "wasm32")))]
417	fn ensure_safe_sqlite_threading_mode() -> Result<()> {
418	    // Ensure SQLite was compiled in threadsafe mode.
419	    if unsafe { ffi::sqlite3_threadsafe() == 0 } {
420	        return Err(Error::SqliteSingleThreadedMode);
421	    }
422	
423	    // Now we know SQLite is _capable_ of being in Multi-thread of Serialized mode,
424	    // but it's possible someone configured it to be in Single-thread mode
425	    // before calling into us. That would mean we're exposing an unsafe API via
426	    // a safe one (in Rust terminology).
427	    //
428	    // We can ask SQLite for a mutex and check for
429	    // the magic value 8. This isn't documented, but it's what SQLite
430	    // returns for its mutex allocation function in Single-thread mode.
431	    const SQLITE_SINGLETHREADED_MUTEX_MAGIC: usize = 8;
432	    let is_singlethreaded = unsafe {
433	        let mutex_ptr = ffi::sqlite3_mutex_alloc(0);
434	        let is_singlethreaded = mutex_ptr as usize == SQLITE_SINGLETHREADED_MUTEX_MAGIC;
435	        ffi::sqlite3_mutex_free(mutex_ptr);
436	        is_singlethreaded
437	    };
438	    if is_singlethreaded {
439	        Err(Error::SqliteSingleThreadedMode)
440	    } else {
441	        Ok(())
442	    }
443	}
