#!/usr/bin/env bash
set -uo pipefail
mkdir -p tests .acceptance-auth
cat > tests/acceptance_try_authorizer.rs <<'RUST'
use rusqlite::{Connection, Error, Result, ffi};
use rusqlite::hooks::{AuthAction, AuthContext, Authorization};
use rusqlite::types::Type;
use std::fmt;
use std::sync::{Arc, Mutex};
use std::sync::atomic::{AtomicBool, AtomicUsize, Ordering};
#[derive(Debug)]
struct PolicyError { tag: u64, detail: String, bytes: Vec<u8> }
impl fmt::Display for PolicyError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result { write!(f, "{}: {}", self.tag, self.detail) }
}
impl std::error::Error for PolicyError {}
fn object(tag: u64) -> PolicyError { PolicyError { tag, detail: format!("policy/{tag}"), bytes: vec![0, 127, 255] } }
fn reason(tag: u64) -> Error { Error::ToSqlConversionFailure(Box::new(object(tag))) }
fn check_object(inner: &(dyn std::error::Error + Send + Sync + 'static), tag: u64) {
    let value = inner.downcast_ref::<PolicyError>().expect("original custom error type was lost");
    assert_eq!(value.tag, tag);
    assert_eq!(value.detail, format!("policy/{tag}"));
    assert_eq!(value.bytes, vec![0, 127, 255]);
}
fn check_reason(error: Error, tag: u64) {
    match error {
        Error::ToSqlConversionFailure(inner) => check_object(inner.as_ref(), tag),
        other => panic!("expected original error {tag}, got {other:?}"),
    }
}
fn deny(error: Error) {
    match error {
        Error::SqliteFailure(code, _) => assert_eq!(code.extended_code, ffi::SQLITE_AUTH),
        other => panic!("expected SQLite authorization error, got {other:?}"),
    }
}
fn db() -> Result<Connection> {
    let c = Connection::open_in_memory()?;
    c.execute_batch("CREATE TABLE foo(x INTEGER UNIQUE, secret TEXT); INSERT INTO foo VALUES(7,'hidden'); CREATE TABLE other(x INTEGER); INSERT INTO other VALUES(11); CREATE TABLE blocked(x INTEGER)")?;
    Ok(c)
}
fn scalar(c: &Connection, sql: &str) -> Result<i64> { c.query_row(sql, [], |r| r.get(0)) }
fn values(c: &Connection) -> Result<Vec<i64>> {
    let mut s = c.prepare("SELECT x FROM foo ORDER BY x")?;
    s.query_map([], |r| r.get(0))?.collect()
}
fn cached(c: &Connection) -> Result<Option<i64>> {
    let mut s = c.prepare_cached("SELECT x FROM foo LIMIT 1")?;
    s.query_row([], |r| r.get(0))
}
fn legacy_denial() -> Result<Error> {
    let mut c = db()?;
    c.authorizer(Some(|ctx: AuthContext<'_>| match ctx.action {
        AuthAction::Insert { table_name: "foo" } => Authorization::Deny,
        _ => Authorization::Allow,
    }))?;
    Ok(c.execute("INSERT INTO foo(x) VALUES(9)", []).unwrap_err())
}

#[test]
fn decisions_mutable_state_and_access_context() -> Result<()> {
    let mut c = db()?;
    c.execute_batch("CREATE VIEW visible AS SELECT x FROM foo; ATTACH DATABASE ':memory:' AS aux; CREATE TABLE aux.item(x INTEGER); INSERT INTO aux.item VALUES(13); CREATE TABLE audit(x INTEGER); CREATE TRIGGER log_foo AFTER INSERT ON foo BEGIN INSERT INTO audit VALUES(new.x); END;")?;
    let seen = Arc::new(Mutex::new(Vec::new()));
    let captured = seen.clone();
    let mut inserts = 0;
    c.try_authorizer(Some(move |ctx: AuthContext<'_>| {
        match ctx.action {
            AuthAction::Read { table_name, column_name } => captured.lock().unwrap().push((format!("read:{table_name}.{column_name}"), ctx.database_name.map(str::to_owned), ctx.accessor.map(str::to_owned))),
            AuthAction::Insert { table_name } => captured.lock().unwrap().push((format!("insert:{table_name}"), ctx.database_name.map(str::to_owned), ctx.accessor.map(str::to_owned))),
            _ => (),
        }
        Ok(match ctx.action {
            AuthAction::Read { table_name: "foo", column_name: "secret" } => Authorization::Ignore,
            AuthAction::Insert { table_name: "foo" } => {
                inserts += 1;
                if inserts == 2 { Authorization::Deny } else { Authorization::Allow }
            }
            _ => Authorization::Allow,
        })
    }))?;
    assert_eq!(c.execute("INSERT INTO foo(x) VALUES(8)", [])?, 1);
    assert_eq!(c.execute("INSERT INTO foo(x) VALUES(9)", []).unwrap_err(), legacy_denial()?);
    let pair: (i64, Option<String>) = c.query_row("SELECT x,secret FROM foo WHERE x=7", [], |r| Ok((r.get(0)?, r.get(1)?)))?;
    assert_eq!(pair, (7, None));
    assert_eq!(scalar(&c, "SELECT x FROM visible WHERE x=7")?, 7);
    assert_eq!(scalar(&c, "SELECT x FROM aux.item")?, 13);
    assert_eq!(scalar(&c, "SELECT x FROM audit")?, 8);
    assert_eq!(values(&c)?, vec![7, 8]);
    let events = seen.lock().unwrap();
    assert!(events.contains(&("read:foo.x".into(), Some("main".into()), Some("visible".into()))));
    assert!(events.contains(&("read:item.x".into(), Some("aux".into()), None)));
    assert!(events.contains(&("insert:audit".into(), Some("main".into()), Some("log_foo".into()))));
    Ok(())
}

#[test]
fn original_variants_objects_and_public_call_results() -> Result<()> {
    let mut c = db()?;
    c.try_authorizer(Some(|ctx: AuthContext<'_>| match ctx.action {
        AuthAction::Read { table_name: "foo", column_name: "x" } => Err(reason(41)),
        AuthAction::Insert { table_name: "foo" } => Err(reason(42)),
        _ => Ok(Authorization::Allow),
    }))?;
    check_reason(c.prepare("SELECT x FROM foo").unwrap_err(), 41);
    check_reason(scalar(&c, "SELECT x FROM foo").unwrap_err(), 41);
    check_reason(c.execute("INSERT INTO foo(x) VALUES(8)", []).unwrap_err(), 42);
    check_reason(c.execute_batch("INSERT INTO foo(x) VALUES(8)").unwrap_err(), 42);
    assert_eq!(scalar(&c, "SELECT COUNT(*) FROM foo")?, 1);
    assert_eq!(scalar(&c, "SELECT x FROM other")?, 11);
    let cases = [
        Error::InvalidParameterName("policy-key".into()),
        Error::IntegralValueOutOfRange(6, -9223372036854775807),
        Error::SqliteFailure(ffi::Error::new(ffi::SQLITE_BUSY), Some("original busy".into())),
        Error::FromSqlConversionFailure(4, Type::Blob, Box::new(object(43))),
        Error::SqlInputError { error: ffi::Error::new(ffi::SQLITE_ERROR), msg: "policy SQL failure".into(), sql: "policy source".into(), offset: 5 },
    ];
    for (index, error) in cases.into_iter().enumerate() {
        let mut pending = Some(error);
        c.try_authorizer(Some(move |ctx: AuthContext<'_>| match ctx.action {
            AuthAction::Insert { table_name: "foo" } => Err(pending.take().expect("unexpected additional failed authorization")),
            _ => Ok(Authorization::Allow),
        }))?;
        let actual = c.execute("INSERT INTO foo(x) VALUES(8)", []).unwrap_err();
        match index {
            0 => assert_eq!(actual, Error::InvalidParameterName("policy-key".into())),
            1 => assert_eq!(actual, Error::IntegralValueOutOfRange(6, -9223372036854775807)),
            2 => assert_eq!(actual, Error::SqliteFailure(ffi::Error::new(ffi::SQLITE_BUSY), Some("original busy".into()))),
            3 => match actual {
                Error::FromSqlConversionFailure(column, kind, inner) => {
                    assert_eq!(column, 4); assert_eq!(kind, Type::Blob); check_object(inner.as_ref(), 43);
                }
                other => panic!("original conversion error was lost: {other:?}"),
            },
            4 => assert_eq!(actual, Error::SqlInputError { error: ffi::Error::new(ffi::SQLITE_ERROR), msg: "policy SQL failure".into(), sql: "policy source".into(), offset: 5 }),
            _ => unreachable!(),
        }
        assert_eq!(scalar(&c, "SELECT COUNT(*) FROM foo")?, 1);
    }
    Ok(())
}

