    c.authorizer(Some(|ctx: AuthContext<'_>| match ctx.action {
        AuthAction::Read { table_name: "foo", column_name: "x" } => Authorization::Ignore,
        _ => Authorization::Allow,
    }))?;
    assert_eq!(cached(&c)?, None);
    c.authorizer(Some(|ctx: AuthContext<'_>| match ctx.action {
        AuthAction::Read { table_name: "foo", column_name: "x" } => Authorization::Deny,
        _ => Authorization::Allow,
    }))?;
    deny(cached(&c).unwrap_err());
    c.try_authorizer(None::<fn(AuthContext<'_>) -> Result<Authorization>>)?;
    assert_eq!(cached(&c)?, Some(7));
    let reject = Arc::new(AtomicBool::new(false)); let flag = reject.clone();
    c.try_authorizer(Some(move |ctx: AuthContext<'_>| {
