        c.try_authorizer(Some(move |ctx: AuthContext<'_>| {
            let targeted = if writing { matches!(ctx.action, AuthAction::Insert { table_name: "foo" }) }
                else { matches!(ctx.action, AuthAction::Read { table_name: "foo", column_name: "x" }) };
            if targeted && flag.load(Ordering::SeqCst) { panic!("reprepare policy panic"); }
            Ok(Authorization::Allow)
        }))?;
        let mut s = c.prepare(if writing { "INSERT INTO foo(x) VALUES(8)" } else { "SELECT x FROM foo" })?;
        reject.store(true, Ordering::SeqCst);
        c.execute_batch("ALTER TABLE foo ADD COLUMN extra INTEGER")?;
        if writing { assert_eq!(s.execute([]).unwrap_err(), Error::UnwindingPanic); }
        else {
            let mut rows = s.query([])?;
            assert_eq!(rows.next().unwrap_err(), Error::UnwindingPanic);
            assert!(rows.next()?.is_none());
        }
        reject.store(false, Ordering::SeqCst);
        if writing { assert_eq!(s.execute([])?, 1); drop(s); assert_eq!(values(&c)?, vec![7, 8]); }
        else { assert_eq!(s.query_row([], |r| r.get::<_, i64>(0))?, 7); }
