    { let mut rows = a.query([])?; check_reason(rows.next().unwrap_err(), 91); }
    assert_eq!(scalar(&c, "SELECT 5")?, 5);
    { let mut rows = b.query([])?; check_reason(rows.next().unwrap_err(), 92); }
    reject.store(false, Ordering::SeqCst);
    assert_eq!(b.query_row([], |r| r.get::<_, i64>(0))?, 11);
    assert_eq!(a.query_row([], |r| r.get::<_, i64>(0))?, 7);
    let mut first = db()?; let mut second = db()?;
    first.try_authorizer(Some(|ctx: AuthContext<'_>| match ctx.action {
        AuthAction::Insert { table_name: "foo" } => Err(reason(101)), _ => Ok(Authorization::Allow),
    }))?;
    second.try_authorizer(Some(|ctx: AuthContext<'_>| match ctx.action {
        AuthAction::Insert { table_name: "foo" } => Err(reason(202)), _ => Ok(Authorization::Allow),
    }))?;
    check_reason(first.execute("INSERT INTO foo(x) VALUES(8)", []).unwrap_err(), 101);
    check_reason(second.execute("INSERT INTO foo(x) VALUES(8)", []).unwrap_err(), 202);
    check_reason(first.execute("INSERT INTO foo(x) VALUES(9)", []).unwrap_err(), 101);
    assert_eq!(values(&first)?, vec![7]); assert_eq!(values(&second)?, vec![7]);
    assert_eq!(db()?.execute("INSERT INTO foo(x) VALUES(8)", [])?, 1);
    Ok(())
}

struct Marker(Arc<AtomicUsize>);
impl Drop for Marker { fn drop(&mut self) { self.0.fetch_add(1, Ordering::SeqCst); } }
fn register_marker(c: &mut Connection, fallible: bool, count: Arc<AtomicUsize>) -> Result<()> {
    let marker = Marker(count);
    if fallible { c.try_authorizer(Some(move |_: AuthContext<'_>| { let _held = &marker; Ok(Authorization::Allow) })) }
    else { c.authorizer(Some(move |_: AuthContext<'_>| { let _held = &marker; Authorization::Allow })) }
}
#[test]
fn shared_registration_removal_and_exactly_once_drops() -> Result<()> {
    let mut c = db()?;
    c.authorizer(Some(|_: AuthContext<'_>| Authorization::Deny))?; deny(c.prepare("SELECT 1").unwrap_err());
    c.try_authorizer(Some(|_: AuthContext<'_>| Ok(Authorization::Allow)))?; assert_eq!(scalar(&c, "SELECT 1")?, 1);
    c.try_authorizer(Some(|_: AuthContext<'_>| Err(reason(111))))?; check_reason(c.prepare("SELECT 1").unwrap_err(), 111);
    c.authorizer(Some(|_: AuthContext<'_>| Authorization::Allow))?; assert_eq!(scalar(&c, "SELECT 1")?, 1);
    c.try_authorizer(Some(|_: AuthContext<'_>| Err(reason(112))))?;
    c.authorizer(None::<fn(AuthContext<'_>) -> Authorization>)?; assert_eq!(scalar(&c, "SELECT 1")?, 1);
    c.authorizer(Some(|_: AuthContext<'_>| Authorization::Deny))?;
    c.try_authorizer(None::<fn(AuthContext<'_>) -> Result<Authorization>>)?; assert_eq!(scalar(&c, "SELECT 1")?, 1);
    c.try_authorizer(Some(|_: AuthContext<'_>| Err(reason(113))))?;
    c.try_authorizer(None::<fn(AuthContext<'_>) -> Result<Authorization>>)?; assert_eq!(scalar(&c, "SELECT 1")?, 1);
    c.authorizer(Some(|_: AuthContext<'_>| Authorization::Deny))?;
    c.authorizer(None::<fn(AuthContext<'_>) -> Authorization>)?; assert_eq!(scalar(&c, "SELECT 1")?, 1);
    let counters: Vec<_> = (0..8).map(|_| Arc::new(AtomicUsize::new(0))).collect();
    for (index, fallible) in [(0, false), (1, true), (2, true), (3, false)] {
        register_marker(&mut c, fallible, counters[index].clone())?;
        assert_eq!(scalar(&c, "SELECT 1")?, 1);
        assert_eq!(counters[index].load(Ordering::SeqCst), 0);
        if index > 0 { assert_eq!(counters[index - 1].load(Ordering::SeqCst), 1); }
    }
    c.try_authorizer(None::<fn(AuthContext<'_>) -> Result<Authorization>>)?; assert_eq!(counters[3].load(Ordering::SeqCst), 1);
    register_marker(&mut c, true, counters[4].clone())?; assert_eq!(scalar(&c, "SELECT 1")?, 1);
    c.authorizer(None::<fn(AuthContext<'_>) -> Authorization>)?; assert_eq!(counters[4].load(Ordering::SeqCst), 1);
    register_marker(&mut c, true, counters[5].clone())?; assert_eq!(scalar(&c, "SELECT 1")?, 1);
    c.close().expect("close failed"); assert_eq!(counters[5].load(Ordering::SeqCst), 1);
    let mut legacy = db()?; register_marker(&mut legacy, false, counters[6].clone())?;
    assert_eq!(scalar(&legacy, "SELECT 1")?, 1); drop(legacy);
    let mut failed = db()?; let marker = Marker(counters[7].clone());
    failed.try_authorizer(Some(move |_: AuthContext<'_>| { let _held = &marker; Err(reason(114)) }))?;
    check_reason(failed.prepare("SELECT 1").unwrap_err(), 114); assert_eq!(counters[7].load(Ordering::SeqCst), 0);
    failed.try_authorizer(None::<fn(AuthContext<'_>) -> Result<Authorization>>)?;
    assert_eq!(scalar(&failed, "SELECT 1")?, 1); drop(failed);
    for counter in counters { assert_eq!(counter.load(Ordering::SeqCst), 1); }
    Ok(())
}

#[derive(Clone, Copy)]
enum Failure { Reason, Deny, Panic }
fn failure(mode: Failure) -> Result<Authorization> {
    match mode { Failure::Reason => Err(reason(121)), Failure::Deny => Ok(Authorization::Deny), Failure::Panic => panic!("batch policy panic") }
}
fn check_failure(error: Error, mode: Failure) {
    match mode { Failure::Reason => check_reason(error, 121), Failure::Deny => deny(error), Failure::Panic => assert_eq!(error, Error::UnwindingPanic) }
}
fn install_blocked(c: &mut Connection, mode: Failure) -> Result<()> {
    c.try_authorizer(Some(move |ctx: AuthContext<'_>| match ctx.action {
        AuthAction::Insert { table_name: "blocked" } => failure(mode), _ => Ok(Authorization::Allow),
    }))
}
#[test]
fn batches_stop_and_caller_controls_transactions() -> Result<()> {
    let sql = "INSERT INTO foo(x) VALUES(8); INSERT INTO blocked VALUES(1); INSERT INTO foo(x) VALUES(9);";
    for mode in [Failure::Reason, Failure::Deny, Failure::Panic] {
        let mut c = db()?; install_blocked(&mut c, mode)?;
        check_failure(c.execute_batch(sql).unwrap_err(), mode);
        assert!(c.is_autocommit()); assert_eq!(values(&c)?, vec![7, 8]);
        assert_eq!(scalar(&c, "SELECT COUNT(*) FROM blocked")?, 0);
        assert_eq!(c.execute("INSERT INTO foo(x) VALUES(10)", [])?, 1);
        check_failure(c.execute("INSERT INTO blocked VALUES(2)", []).unwrap_err(), mode);
        assert_eq!(values(&c)?, vec![7, 8, 10]);
        for commit in [false, true] {
            let mut c = db()?; install_blocked(&mut c, mode)?;
            let tx = c.transaction()?;
            check_failure(tx.execute_batch(sql).unwrap_err(), mode);
            assert!(!tx.is_autocommit(), "authorization failure ended caller transaction");
            assert_eq!(values(&tx)?, vec![7, 8]);
            assert_eq!(scalar(&tx, "SELECT COUNT(*) FROM blocked")?, 0);
            assert_eq!(tx.execute("INSERT INTO foo(x) VALUES(10)", [])?, 1);
            if commit { tx.commit()?; } else { tx.rollback()?; }
            assert!(c.is_autocommit());
            assert_eq!(values(&c)?, if commit { vec![7, 8, 10] } else { vec![7] });
            assert_eq!(scalar(&c, "SELECT COUNT(*) FROM blocked")?, 0);
        }
    }
    Ok(())
}
