                            break rc;
                        }
                        rc = unlock_notify::wait_for_unlock_notify(db);
                        if rc != ffi::SQLITE_OK {
                            break rc;
                        }
                        self.reset();
                    }
                }
            }
            _ => {
                // no_fmt
                unsafe { ffi::sqlite3_step(self.ptr) }
            }
        }
    }

