```rust
/// The original error a scalar function registered with
/// [`Connection::try_create_scalar_function`] reported most recently.
/// Stored on the connection (see [`InnerConnection::set_clientdata`]) so
/// that the error can cross the SQLite boundary: the callback reports a
/// generic SQLite error to the engine, and the first rusqlite call that
/// observes that error takes and returns the original one instead.
struct ScalarFnErrorState {
    error: Option<Error>,
}

/// Give the original error of a failing scalar function to the connection
/// slot, to be picked up by [`take_scalar_function_error`] when the database
/// call that triggered the failure decodes SQLite's error.
unsafe fn stash_scalar_fn_error(ctx: *mut sqlite3_context, error: Error) {
    unsafe {
        let db = ffi::sqlite3_context_db_handle(ctx);
        if db.is_null() {
            return;
        }
        let state = ffi::sqlite3_get_clientdata(db, SCALAR_FN_ERROR_SLOT.as_ptr())
            .cast::<ScalarFnErrorState>();
        if state.is_null() {
            return;
        }
        (*state).error = Some(error);
    }
}

/// If a scalar function registered with [`Connection::try_create_scalar_function`]
/// on `db` reported an error that has not been delivered yet, take and return
/// it. The error is consumed, so it is reported at most once, by the call that
/// triggered the failure.
pub(crate) unsafe fn take_scalar_function_error(
    db: *mut ffi::sqlite3,
    _code: c_int,
) -> Option<Error> {
    if db.is_null() {
        return None;
    }
    let state = unsafe { ffi::sqlite3_get_clientdata(db, SCALAR_FN_ERROR_SLOT.as_ptr()) }
        .cast::<ScalarFnErrorState>();
    if state.is_null() {
        return None;
    }
    unsafe { (*state).error.take() }
}
```

