    flags: FunctionFlags,
    x_func: F,
) -> Result<()>
where
    F: Fn(&Context<'_>) -> Result<T> + Send + 'static,
    T: SqlFnOutput,
{
    self.try_create_scalar_function(fn_name, n_arg, flags, x_func)
}

