#[test]
fn failure_inside_aggregate_query() -> Result<()> {
    let db = Connection::open_in_memory()?;
    db.execute_batch("CREATE TABLE t(x INTEGER); INSERT INTO t VALUES (1),(2),(3);")?;
    db.try_create_scalar_function(c"agg_fail", 1, flags(), |ctx| {
        let x = ctx.get::<i64>(0)?;
        if x == 2 {
            return Err(fn_error(97));
        }
        Ok(x)
    })?;
    // the function fails while SQLite is stepping an aggregate
    assert_fn_error(
        &db.one_column::<i64, _>("SELECT sum(agg_fail(x)) FROM t", [])
            .unwrap_err(),
        97,
    );
    // the connection stays usable
    assert_eq!(db.one_column::<i64, _>("SELECT sum(x) FROM t", [])?, 6);
    Ok(())
}

#[test]
fn returning_clause_reports_during_iteration() -> Result<()> {
    let db = Connection::open_in_memory()?;
    db.execute_batch("CREATE TABLE t(x INTEGER)")?;
    db.try_create_scalar_function(c"ret_fail", 1, flags(), |ctx| {
        let x = ctx.get::<i64>(0)?;
        if x == 2 {
            return Err(fn_error(99));
        }
        Ok(x)
    })?;
    let mut stmt =
        db.prepare("INSERT INTO t VALUES (ret_fail(1)), (ret_fail(2)) RETURNING x")?;
    let mut rows = stmt.query([])?;
    {
        // a row already returned is not a delivered error
        let row = rows.next()?.expect("first row");
        assert_eq!(row.get::<_, i64>(0)?, 1);
    }
    // iterating to the failing row reports the original error
    assert_fn_error(&rows.next().unwrap_err(), 99);
    assert!(rows.next()?.is_none());
    Ok(())
}

